        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        long shares = (long) in.nval;
        long[] quantity = new long[n], price = new long[n], timestamp = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken(); quantity[i] = (long) in.nval;
            in.nextToken(); price[i] = (long) in.nval;
            in.nextToken(); timestamp[i] = (long) in.nval;
        }
        int[] res = noShareUsers(quantity, price, timestamp, shares);
        if (res.length == 0) { System.out.println(-1); return; }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < res.length; i++) sb.append(res[i]).append(i + 1 < res.length ? " " : "\n");
        System.out.print(sb);
